package forth

import (
	"errors"
	"strconv"
	"strings"
)

// op is a single primitive operation. When word is empty the op pushes num
// onto the data stack; otherwise it executes the named built-in word.
type op struct {
	num  int
	word string
}

// builtins are the words the evaluator supports out of the box.
var builtins = map[string]bool{
	"+": true, "-": true, "*": true, "/": true,
	"dup": true, "drop": true, "swap": true, "over": true,
}

// interp holds the Forth data stack and the user-defined words.
type interp struct {
	stack []int
	words map[string][]op
}

// Forth evaluates a sequence of Forth lines and returns the final data stack.
// A non-nil error is returned when the input cannot be evaluated.
func Forth(input []string) ([]int, error) {
	f := &interp{
		stack: []int{},
		words: map[string][]op{},
	}
	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			if err := f.define(tokens); err != nil {
				return nil, err
			}
			continue
		}
		if err := f.execute(tokens); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

// define parses a ": name body ;" definition line.
func (f *interp) define(tokens []string) error {
	if len(tokens) < 2 {
		return errors.New("malformed word definition")
	}
	name := strings.ToLower(tokens[1])
	if isNumber(tokens[1]) {
		return errors.New("cannot define a number as a word")
	}
	var body []op
	closed := false
	for _, tok := range tokens[2:] {
		if tok == ";" {
			closed = true
			break
		}
		o, err := f.resolve(tok)
		if err != nil {
			return err
		}
		body = append(body, o...)
	}
	if !closed {
		return errors.New("word definition not terminated with ;")
	}
	f.words[name] = body
	return nil
}

// execute runs a line of (non-definition) tokens.
func (f *interp) execute(tokens []string) error {
	for _, tok := range tokens {
		o, err := f.resolve(tok)
		if err != nil {
			return err
		}
		for _, p := range o {
			if err := f.run(p); err != nil {
				return err
			}
		}
	}
	return nil
}

// resolve turns a token into the primitive operations it represents.
// User-defined words are expanded to their (already flattened) bodies so that
// a later redefinition of a word does not affect words that were compiled
// earlier.
func (f *interp) resolve(tok string) ([]op, error) {
	if isNumber(tok) {
		n, _ := strconv.Atoi(tok)
		return []op{{num: n}}, nil
	}
	name := strings.ToLower(tok)
	if def, ok := f.words[name]; ok {
		return def, nil
	}
	if builtins[name] {
		return []op{{word: name}}, nil
	}
	return nil, errors.New("undefined operation: " + tok)
}

// run executes a single primitive operation against the data stack.
func (f *interp) run(o op) error {
	switch o.word {
	case "":
		f.push(o.num)
	case "+":
		return f.add()
	case "-":
		return f.sub()
	case "*":
		return f.mul()
	case "/":
		return f.div()
	case "dup":
		return f.dup()
	case "drop":
		return f.drop()
	case "swap":
		return f.swap()
	case "over":
		return f.over()
	}
	return nil
}

func (f *interp) push(n int) {
	f.stack = append(f.stack, n)
}

func (f *interp) pop() (int, error) {
	if len(f.stack) == 0 {
		return 0, errors.New("empty stack")
	}
	n := len(f.stack)
	v := f.stack[n-1]
	f.stack = f.stack[:n-1]
	return v, nil
}

// pop2 returns the two top values with a (second) and b (top).
func (f *interp) pop2() (int, int, error) {
	if len(f.stack) < 2 {
		return 0, 0, errors.New("insufficient values on the stack")
	}
	n := len(f.stack)
	a := f.stack[n-2]
	b := f.stack[n-1]
	f.stack = f.stack[:n-2]
	return a, b, nil
}

func (f *interp) add() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(a + b)
	return nil
}

func (f *interp) sub() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(a - b)
	return nil
}

func (f *interp) mul() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(a * b)
	return nil
}

func (f *interp) div() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	if b == 0 {
		return errors.New("division by zero")
	}
	f.push(a / b)
	return nil
}

func (f *interp) dup() error {
	a, err := f.pop()
	if err != nil {
		return err
	}
	f.push(a)
	f.push(a)
	return nil
}

func (f *interp) drop() error {
	_, err := f.pop()
	return err
}

func (f *interp) swap() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(b)
	f.push(a)
	return nil
}

func (f *interp) over() error {
	if len(f.stack) < 2 {
		return errors.New("insufficient values on the stack")
	}
	a := f.stack[len(f.stack)-2]
	f.push(a)
	return nil
}

// isNumber reports whether s is a signed integer: an optional leading minus
// followed by one or more ASCII digits.
func isNumber(s string) bool {
	if s == "" {
		return false
	}
	i := 0
	if s[0] == '-' {
		i = 1
	}
	if i >= len(s) {
		return false
	}
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}
